/**
 * Database schema (PostgreSQL).
 *
 * Conventions:
 * - Primary keys are UUIDs (RFC 9562) generated by the database.
 * - Every timestamp is a `timestamptz` stored in UTC and exchanged as ISO 8601.
 * - Country codes are ISO 3166-1 alpha-2, locales are BCP 47 tags (ISO 639 language + ISO 3166 region),
 *   time zones are IANA tz database names.
 * - Slugs follow WorkAdventure's play URL format: /@/{organization}/{world}/{room}.
 */
import { sql } from "drizzle-orm";
import {
    type AnyPgColumn,
    boolean,
    check,
    customType,
    foreignKey,
    index,
    inet,
    integer,
    jsonb,
    pgEnum,
    pgTable,
    primaryKey,
    text,
    timestamp,
    unique,
    uniqueIndex,
    uuid,
    varchar,
} from "drizzle-orm/pg-core";
import type { WorldSettings } from "../../settings/worldSettings";
import type { InstanceSettings } from "../../settings/instanceSettings";
import type { IntegrationActivity, IntegrationSettings } from "../../settings/integrationSettings";
import type { PresenceEntry } from "../../presence/model";

/** Binary data (PostgreSQL bytea), exchanged as a Node.js Buffer. */
const bytea = customType<{ data: Buffer; driverData: Buffer }>({
    dataType() {
        return "bytea";
    },
});

const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
    timestamp("updated_at", { withTimezone: true })
        .notNull()
        .defaultNow()
        .$onUpdate(() => new Date());

// ---------------------------------------------------------------------------------------------
// Back-office identities
// ---------------------------------------------------------------------------------------------

export const accountStatus = pgEnum("account_status", ["active", "disabled"]);

/** People who log into this back office. */
export const accounts = pgTable(
    "accounts",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        email: varchar("email", { length: 320 }).notNull(),
        name: varchar("name", { length: 200 }).notNull(),
        passwordHash: text("password_hash").notNull(),
        isSuperadmin: boolean("is_superadmin").notNull().default(false),
        status: accountStatus("status").notNull().default("active"),
        locale: varchar("locale", { length: 35 }),
        timeZone: varchar("time_zone", { length: 64 }),
        totpSecret: text("totp_secret"),
        totpEnabledAt: timestamp("totp_enabled_at", { withTimezone: true }),
        /** Last accepted TOTP time step (unix time / 30): a code is never accepted twice (replay). */
        totpLastStep: integer("totp_last_step"),
        /** Consecutive invalid second-factor codes; reaching the limit locks the second factor. */
        totpFailedCount: integer("totp_failed_count").notNull().default(0),
        totpLockedUntil: timestamp("totp_locked_until", { withTimezone: true }),
        /** Set when a superadmin issued a temporary password: the person must choose a new one. */
        mustChangePassword: boolean("must_change_password").notNull().default(false),
        failedLoginCount: integer("failed_login_count").notNull().default(0),
        lockedUntil: timestamp("locked_until", { withTimezone: true }),
        lastLoginAt: timestamp("last_login_at", { withTimezone: true }),
        passwordChangedAt: timestamp("password_changed_at", { withTimezone: true }).notNull().defaultNow(),
        /**
         * When the person proved they receive mail at `email` (registration link, emailed invitation).
         * Accounts created by administrators before this column existed count as verified.
         */
        emailVerifiedAt: timestamp("email_verified_at", { withTimezone: true }),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
    },
    (t) => [uniqueIndex("accounts_email_unique").on(sql`lower(${t.email})`)],
);

export const sessions = pgTable(
    "sessions",
    {
        /** SHA-256 of the session token: the token itself is only ever in the user's cookie. */
        id: varchar("id", { length: 64 }).primaryKey(),
        accountId: uuid("account_id")
            .notNull()
            .references(() => accounts.id, { onDelete: "cascade" }),
        expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
        /** Set once a second factor has been verified for this session. */
        mfaVerified: boolean("mfa_verified").notNull().default(false),
        ipAddress: inet("ip_address"),
        userAgent: text("user_agent"),
        createdAt: createdAt(),
        lastSeenAt: timestamp("last_seen_at", { withTimezone: true }).notNull().defaultNow(),
    },
    (t) => [index("sessions_account_idx").on(t.accountId)],
);

/** Single-use second-factor recovery codes. Only a keyed hash (HMAC with APP_SECRET) is stored. */
export const recoveryCodes = pgTable(
    "recovery_codes",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        accountId: uuid("account_id")
            .notNull()
            .references(() => accounts.id, { onDelete: "cascade" }),
        codeHash: varchar("code_hash", { length: 64 }).notNull(),
        usedAt: timestamp("used_at", { withTimezone: true }),
        createdAt: createdAt(),
    },
    (t) => [
        index("recovery_codes_account_idx").on(t.accountId),
        uniqueIndex("recovery_codes_account_hash_unique").on(t.accountId, t.codeHash),
    ],
);

/**
 * Fixed-window rate-limit counters, shared by every instance of the application.
 * `key` names the limited action and subject, e.g. "login:ip:203.0.113.7".
 */
export const rateLimits = pgTable(
    "rate_limits",
    {
        key: varchar("key", { length: 200 }).primaryKey(),
        windowStart: timestamp("window_start", { withTimezone: true }).notNull(),
        count: integer("count").notNull(),
        expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    },
    (t) => [index("rate_limits_expires_idx").on(t.expiresAt)],
);

// ---------------------------------------------------------------------------------------------
// Tenancy: organization > workspace > world > room
//
// A workspace is an AdminSpace-only grouping of worlds (a department, a site): the unit of delegated
// administration and of employee access. WorkAdventure never sees it; its URLs stay
// /@/{organization}/{world}/{room}.
// ---------------------------------------------------------------------------------------------

export const organizationStatus = pgEnum("organization_status", ["active", "suspended"]);

export const organizations = pgTable(
    "organizations",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        slug: varchar("slug", { length: 64 }).notNull(),
        name: varchar("name", { length: 200 }).notNull(),
        /** ISO 3166-1 alpha-2 */
        countryCode: varchar("country_code", { length: 2 }),
        /** BCP 47 */
        defaultLocale: varchar("default_locale", { length: 35 }).notNull().default("en-US"),
        contactEmail: varchar("contact_email", { length: 320 }),
        /** http(s) URL of the logo shown in the back office (an uploaded asset or an external image). */
        logoUrl: text("logo_url"),
        /** Hex color (#RRGGBB) of the organization, used in the back office only. */
        brandColor: varchar("brand_color", { length: 7 }),
        /** Set by platform administrators. A suspended organization's worlds refuse everyone. */
        status: organizationStatus("status").notNull().default("active"),
        suspendedAt: timestamp("suspended_at", { withTimezone: true }),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
    },
    (t) => [uniqueIndex("organizations_slug_unique").on(t.slug)],
);

/**
 * Organization-wide roles. `employee` has no administrative right: it sees the employee workspace
 * (offices, teammates, components) and enters the worlds of the workspaces it is a member of.
 */
export const organizationRole = pgEnum("organization_role", ["owner", "admin", "moderator", "viewer", "employee"]);

export const membershipStatus = pgEnum("membership_status", ["active", "suspended"]);

/** Who belongs to an organization in this back office, and with which organization-wide role. */
export const organizationMemberships = pgTable(
    "organization_memberships",
    {
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        accountId: uuid("account_id")
            .notNull()
            .references(() => accounts.id, { onDelete: "cascade" }),
        role: organizationRole("role").notNull(),
        /** A suspended membership grants nothing (back office and WorkAdventure) but keeps its assignments. */
        status: membershipStatus("status").notNull().default("active"),
        suspendedAt: timestamp("suspended_at", { withTimezone: true }),
        /** Who added or invited this person. */
        invitedBy: uuid("invited_by").references(() => accounts.id, { onDelete: "set null" }),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
    },
    (t) => [
        primaryKey({ columns: [t.organizationId, t.accountId] }),
        index("organization_memberships_account_idx").on(t.accountId),
    ],
);

export const workspaces = pgTable(
    "workspaces",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        slug: varchar("slug", { length: 64 }).notNull(),
        name: varchar("name", { length: 200 }).notNull(),
        description: text("description"),
        position: integer("position").notNull().default(0),
        /** Archiving a workspace archives its active worlds with the same timestamp (restored together). */
        archivedAt: timestamp("archived_at", { withTimezone: true }),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
    },
    (t) => [
        uniqueIndex("workspaces_org_slug_unique").on(t.organizationId, t.slug),
        // Target of the composite foreign keys below: a world or an assignment can only reference a
        // workspace of its own organization.
        unique("workspaces_org_id_unique").on(t.organizationId, t.id),
    ],
);

export const workspaceRole = pgEnum("workspace_role", ["manager", "member"]);

/**
 * Workspace-scoped roles. `manager` administers the workspace's worlds (delegated administration);
 * `member` lets an employee enter them. Removing the organization membership removes these rows.
 */
export const workspaceMemberships = pgTable(
    "workspace_memberships",
    {
        workspaceId: uuid("workspace_id").notNull(),
        organizationId: uuid("organization_id").notNull(),
        accountId: uuid("account_id").notNull(),
        role: workspaceRole("role").notNull(),
        createdBy: uuid("created_by").references(() => accounts.id, { onDelete: "set null" }),
        createdAt: createdAt(),
    },
    (t) => [
        primaryKey({ columns: [t.workspaceId, t.accountId] }),
        foreignKey({
            name: "workspace_memberships_workspace_fk",
            columns: [t.organizationId, t.workspaceId],
            foreignColumns: [workspaces.organizationId, workspaces.id],
        }).onDelete("cascade"),
        foreignKey({
            name: "workspace_memberships_membership_fk",
            columns: [t.organizationId, t.accountId],
            foreignColumns: [organizationMemberships.organizationId, organizationMemberships.accountId],
        }).onDelete("cascade"),
        index("workspace_memberships_account_idx").on(t.accountId),
    ],
);

export const worldAccessPolicy = pgEnum("world_access_policy", ["public", "authenticated", "members"]);

export const worlds = pgTable(
    "worlds",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        /** Administrative grouping only: moving a world between workspaces does not change its URL. */
        workspaceId: uuid("workspace_id").notNull(),
        slug: varchar("slug", { length: 64 }).notNull(),
        name: varchar("name", { length: 200 }).notNull(),
        description: text("description"),
        accessPolicy: worldAccessPolicy("access_policy").notNull().default("public"),
        /** 0 means unlimited. */
        maxUsers: integer("max_users").notNull().default(0),
        expiresAt: timestamp("expires_at", { withTimezone: true }),
        archivedAt: timestamp("archived_at", { withTimezone: true }),
        /** Typed and validated by WorldSettings (src/lib/settings/worldSettings.ts). */
        settings: jsonb("settings").$type<WorldSettings>().notNull().default({}),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
    },
    (t) => [
        uniqueIndex("worlds_org_slug_unique").on(t.organizationId, t.slug),
        // Target of composite foreign keys: rows that name a world also name its organization.
        unique("worlds_org_id_unique").on(t.organizationId, t.id),
        index("worlds_workspace_idx").on(t.workspaceId),
        // A workspace is never deleted while it holds worlds; it must be emptied first.
        foreignKey({
            name: "worlds_workspace_fk",
            columns: [t.organizationId, t.workspaceId],
            foreignColumns: [workspaces.organizationId, workspaces.id],
        }).onDelete("restrict"),
    ],
);

export const mapKind = pgEnum("map_kind", ["tmj", "wam"]);
export const roomSyncState = pgEnum("room_sync_state", ["ready", "pending", "failed"]);

export const rooms = pgTable(
    "rooms",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        worldId: uuid("world_id")
            .notNull()
            .references(() => worlds.id, { onDelete: "cascade" }),
        slug: varchar("slug", { length: 128 }).notNull(),
        name: varchar("name", { length: 200 }).notNull(),
        description: text("description"),
        mapKind: mapKind("map_kind").notNull().default("wam"),
        /** Tiled map (.tmj/.json) URL, for mapKind = tmj. */
        mapUrl: text("map_url"),
        /** Map-storage WAM URL, for mapKind = wam. */
        wamUrl: text("wam_url"),
        /** The room people land in when they open the world URL without a room. */
        isDefault: boolean("is_default").notNull().default(false),
        /** When not empty, only members holding at least one of these tags may enter. */
        requiredTags: text("required_tags")
            .array()
            .notNull()
            .default(sql`'{}'::text[]`),
        position: integer("position").notNull().default(0),
        thumbnailUrl: text("thumbnail_url"),
        /**
         * State of the room's map in WorkAdventure when AdminSpace changes it (room templates uploaded to
         * map-storage, component collection added to the WAM): "ready" unless a job is pending or failed.
         */
        syncState: roomSyncState("sync_state").notNull().default("ready"),
        /** Short, sanitized error of the last failed synchronization. */
        syncError: text("sync_error"),
        /** When the world's component collection was confirmed in this room's WAM file. */
        collectionLinkedAt: timestamp("collection_linked_at", { withTimezone: true }),
        /** The room template version this room was created from, if any. */
        templateVersionId: uuid("template_version_id"),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
    },
    (t) => [
        uniqueIndex("rooms_world_slug_unique").on(t.worldId, t.slug),
        // Map-storage's webhook looks rooms up by map on every map change (services/mapStorageWebhook.ts). Hash:
        // equality only, and no key size limit for long URLs.
        index("rooms_wam_url_idx").using("hash", t.wamUrl),
    ],
);

// ---------------------------------------------------------------------------------------------
// People inside WorkAdventure worlds
// ---------------------------------------------------------------------------------------------

export const memberKind = pgEnum("member_kind", ["member", "guest"]);

/**
 * A person known in a world. `uuid` is the identifier WorkAdventure uses (userUuid); logged-in
 * people are identified by their email, anonymous ones by a random UUID chosen by the pusher.
 */
export const members = pgTable(
    "members",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        worldId: uuid("world_id")
            .notNull()
            .references(() => worlds.id, { onDelete: "cascade" }),
        uuid: varchar("uuid", { length: 320 }).notNull(),
        kind: memberKind("kind").notNull().default("guest"),
        email: varchar("email", { length: 320 }),
        name: varchar("name", { length: 200 }),
        visitCardUrl: text("visit_card_url"),
        chatId: varchar("chat_id", { length: 320 }),
        characterTextureIds: text("character_texture_ids")
            .array()
            .notNull()
            .default(sql`'{}'::text[]`),
        companionTextureId: varchar("companion_texture_id", { length: 128 }),
        locale: varchar("locale", { length: 35 }),
        lastSeenAt: timestamp("last_seen_at", { withTimezone: true }),
        visitCount: integer("visit_count").notNull().default(0),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
    },
    (t) => [
        uniqueIndex("members_world_uuid_unique").on(t.worldId, t.uuid),
        uniqueIndex("members_world_email_unique")
            .on(t.worldId, sql`lower(${t.email})`)
            .where(sql`${t.email} is not null`),
        index("members_world_last_seen_idx").on(t.worldId, t.lastSeenAt),
    ],
);

export const tags = pgTable(
    "tags",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        worldId: uuid("world_id")
            .notNull()
            .references(() => worlds.id, { onDelete: "cascade" }),
        name: varchar("name", { length: 64 }).notNull(),
        description: text("description"),
        /** Hex color (#RRGGBB) used in the back office only. */
        color: varchar("color", { length: 7 }),
        createdAt: createdAt(),
    },
    (t) => [uniqueIndex("tags_world_name_unique").on(t.worldId, t.name)],
);

export const memberTags = pgTable(
    "member_tags",
    {
        memberId: uuid("member_id")
            .notNull()
            .references(() => members.id, { onDelete: "cascade" }),
        tagId: uuid("tag_id")
            .notNull()
            .references(() => tags.id, { onDelete: "cascade" }),
    },
    (t) => [primaryKey({ columns: [t.memberId, t.tagId] })],
);

/**
 * Employee profile of a person in an organization (docs/MEMBERS.md): job title, department, manager, work location.
 * Keyed by the person's email in lower case, the identifier WorkAdventure and the back office share for signed-in
 * people: one profile serves the person's member rows in every world of the organization and their account. The
 * manager is another profile of the same organization (checked by src/lib/server/services/memberProfiles.ts, which
 * also refuses reporting cycles); deleting a profile leaves its direct reports without a manager.
 */
export const memberProfiles = pgTable(
    "member_profiles",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        /** Lower case. */
        email: varchar("email", { length: 320 }).notNull(),
        jobTitle: varchar("job_title", { length: 200 }),
        department: varchar("department", { length: 200 }),
        /** Free text, e.g. "Paris office" or "Remote". */
        workLocation: varchar("work_location", { length: 200 }),
        managerId: uuid("manager_id").references((): AnyPgColumn => memberProfiles.id, { onDelete: "set null" }),
        updatedBy: uuid("updated_by").references(() => accounts.id, { onDelete: "set null" }),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
    },
    (t) => [
        uniqueIndex("member_profiles_org_email_unique").on(t.organizationId, t.email),
        index("member_profiles_org_department_idx").on(t.organizationId, t.department),
        index("member_profiles_manager_idx").on(t.managerId),
        check("member_profiles_email_lower_check", sql`${t.email} = lower(${t.email})`),
        check("member_profiles_manager_check", sql`${t.managerId} is null or ${t.managerId} <> ${t.id}`),
    ],
);

export const bans = pgTable(
    "bans",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        worldId: uuid("world_id")
            .notNull()
            .references(() => worlds.id, { onDelete: "cascade" }),
        memberUuid: varchar("member_uuid", { length: 320 }),
        ipAddress: inet("ip_address"),
        name: varchar("name", { length: 200 }),
        reason: text("reason").notNull(),
        /** userUuid of the in-game admin, or "account:<id>" when banned from the back office. */
        bannedBy: varchar("banned_by", { length: 400 }).notNull(),
        expiresAt: timestamp("expires_at", { withTimezone: true }),
        revokedAt: timestamp("revoked_at", { withTimezone: true }),
        revokedBy: uuid("revoked_by").references(() => accounts.id, { onDelete: "set null" }),
        createdAt: createdAt(),
    },
    (t) => [
        index("bans_world_member_idx").on(t.worldId, t.memberUuid),
        index("bans_world_ip_idx").on(t.worldId, t.ipAddress),
    ],
);

export const reportStatus = pgEnum("report_status", ["open", "resolved", "dismissed"]);

export const reports = pgTable(
    "reports",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        worldId: uuid("world_id")
            .notNull()
            .references(() => worlds.id, { onDelete: "cascade" }),
        roomUrl: text("room_url").notNull(),
        reportedUuid: varchar("reported_uuid", { length: 320 }).notNull(),
        reporterUuid: varchar("reporter_uuid", { length: 320 }).notNull(),
        comment: text("comment").notNull(),
        status: reportStatus("status").notNull().default("open"),
        resolutionNote: text("resolution_note"),
        handledBy: uuid("handled_by").references(() => accounts.id, { onDelete: "set null" }),
        handledAt: timestamp("handled_at", { withTimezone: true }),
        createdAt: createdAt(),
    },
    (t) => [index("reports_world_status_idx").on(t.worldId, t.status)],
);

// ---------------------------------------------------------------------------------------------
// Avatar catalog (Woka textures and companions), shared by every world
// ---------------------------------------------------------------------------------------------

/** Woka part types, as WorkAdventure names them (see wokaPartNames in the contract). */
export const wokaPart = pgEnum("woka_part", ["woka", "body", "eyes", "hair", "clothes", "hat", "accessory"]);

export const wokaCollections = pgTable(
    "woka_collections",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        part: wokaPart("part").notNull(),
        name: varchar("name", { length: 100 }).notNull(),
        position: integer("position").notNull().default(0),
    },
    (t) => [uniqueIndex("woka_collections_part_name_unique").on(t.part, t.name)],
);

export const wokaTextures = pgTable("woka_textures", {
    /** Texture ids are chosen by WorkAdventure's catalog (e.g. "male1") and kept stable. */
    id: varchar("id", { length: 128 }).primaryKey(),
    collectionId: uuid("collection_id")
        .notNull()
        .references(() => wokaCollections.id, { onDelete: "cascade" }),
    name: varchar("name", { length: 100 }).notNull(),
    url: text("url").notNull(),
    tintable: boolean("tintable").notNull().default(false),
    enabled: boolean("enabled").notNull().default(true),
    position: integer("position").notNull().default(0),
});

export const companionBehavior = pgEnum("companion_behavior", ["cat", "dog", "red_panda"]);

export const companionCollections = pgTable(
    "companion_collections",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        name: varchar("name", { length: 100 }).notNull(),
        position: integer("position").notNull().default(0),
    },
    (t) => [uniqueIndex("companion_collections_name_unique").on(t.name)],
);

export const companionTextures = pgTable("companion_textures", {
    id: varchar("id", { length: 128 }).primaryKey(),
    collectionId: uuid("collection_id")
        .notNull()
        .references(() => companionCollections.id, { onDelete: "cascade" }),
    name: varchar("name", { length: 100 }).notNull(),
    url: text("url").notNull(),
    behavior: companionBehavior("behavior"),
    enabled: boolean("enabled").notNull().default(true),
    position: integer("position").notNull().default(0),
});

// ---------------------------------------------------------------------------------------------
// Integration
// ---------------------------------------------------------------------------------------------

/** Keys for WorkAdventure's Room API (checked through /api/room-api/authorization). */
export const roomApiKeys = pgTable(
    "room_api_keys",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        /** Restricts the key to one world; null means every world of the organization. */
        worldId: uuid("world_id").references(() => worlds.id, { onDelete: "cascade" }),
        name: varchar("name", { length: 200 }).notNull(),
        /** SHA-256 of the key. The clear key is shown once, at creation. */
        keyHash: varchar("key_hash", { length: 64 }).notNull(),
        keyPrefix: varchar("key_prefix", { length: 16 }).notNull(),
        createdBy: uuid("created_by").references(() => accounts.id, { onDelete: "set null" }),
        lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
        expiresAt: timestamp("expires_at", { withTimezone: true }),
        revokedAt: timestamp("revoked_at", { withTimezone: true }),
        createdAt: createdAt(),
    },
    (t) => [uniqueIndex("room_api_keys_hash_unique").on(t.keyHash)],
);

/** Custom domains an organization serves WorkAdventure on (for /api/domain/verify). */
export const domains = pgTable(
    "domains",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        host: varchar("host", { length: 253 }).notNull(),
        /** Token answered on /white-label/cf-challenge for this host. */
        challenge: varchar("challenge", { length: 128 }),
        verifiedAt: timestamp("verified_at", { withTimezone: true }),
        createdAt: createdAt(),
    },
    (t) => [uniqueIndex("domains_host_unique").on(sql`lower(${t.host})`)],
);

/** Singleton row holding instance-wide settings (connection to WorkAdventure, defaults). */
export const instanceSettings = pgTable("instance_settings", {
    id: integer("id").primaryKey().default(1),
    settings: jsonb("settings").$type<InstanceSettings>().notNull().default({}),
    updatedAt: updatedAt(),
});

// ---------------------------------------------------------------------------------------------
// Logs
// ---------------------------------------------------------------------------------------------

/** Append-only record of administrative actions (who did what, when, from where). */
export const auditLogs = pgTable(
    "audit_logs",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        occurredAt: timestamp("occurred_at", { withTimezone: true }).notNull().defaultNow(),
        /** null for actions made by WorkAdventure itself through the Admin API. */
        accountId: uuid("account_id").references(() => accounts.id, { onDelete: "set null" }),
        actorLabel: varchar("actor_label", { length: 400 }).notNull(),
        organizationId: uuid("organization_id").references(() => organizations.id, { onDelete: "set null" }),
        worldId: uuid("world_id").references(() => worlds.id, { onDelete: "set null" }),
        action: varchar("action", { length: 100 }).notNull(),
        targetType: varchar("target_type", { length: 50 }),
        targetId: varchar("target_id", { length: 400 }),
        ipAddress: inet("ip_address"),
        details: jsonb("details").$type<Record<string, unknown>>(),
    },
    (t) => [
        index("audit_logs_org_time_idx").on(t.organizationId, t.occurredAt),
        index("audit_logs_world_time_idx").on(t.worldId, t.occurredAt),
    ],
);

/** Recording lifecycle events posted by the back (POST /api/recordings/events). */
export const recordingEvents = pgTable(
    "recording_events",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        worldId: uuid("world_id").references(() => worlds.id, { onDelete: "cascade" }),
        egressId: varchar("egress_id", { length: 128 }).notNull(),
        status: varchar("status", { length: 64 }).notNull(),
        playUri: text("play_uri").notNull(),
        recorderUuid: varchar("recorder_uuid", { length: 320 }).notNull(),
        startedAt: timestamp("started_at", { withTimezone: true }),
        endedAt: timestamp("ended_at", { withTimezone: true }),
        error: text("error"),
        files: jsonb("files").$type<{ filename: string; sizeBytes: number; durationSeconds: number }[]>().notNull(),
        receivedAt: timestamp("received_at", { withTimezone: true }).notNull().defaultNow(),
    },
    (t) => [uniqueIndex("recording_events_egress_unique").on(t.egressId)],
);

/** Analytics events posted by pushers (POST /api/analytics/events-batch), idempotent on eventId. */
export const analyticsEvents = pgTable(
    "analytics_events",
    {
        eventId: varchar("event_id", { length: 128 }).primaryKey(),
        worldId: uuid("world_id")
            .notNull()
            .references(() => worlds.id, { onDelete: "cascade" }),
        eventName: varchar("event_name", { length: 128 }).notNull(),
        source: varchar("source", { length: 32 }).notNull(),
        roomId: text("room_id").notNull(),
        /** Pseudonymous: a keyed hash of the userUuid, never the raw identifier. */
        actorHash: varchar("actor_hash", { length: 64 }).notNull(),
        occurredAt: timestamp("occurred_at", { withTimezone: true }).notNull(),
        properties: jsonb("properties").$type<Record<string, unknown>>().notNull(),
    },
    (t) => [index("analytics_events_world_time_idx").on(t.worldId, t.occurredAt)],
);

// ---------------------------------------------------------------------------------------------
// Onboarding and identity lifecycle
//
// Secret links (invitations, registration, password reset) carry a 256-bit random token; only its
// SHA-256 is stored, so a database leak does not leak usable links. Every token is single use and
// expires.
// ---------------------------------------------------------------------------------------------

/** Invitation of a person, by email, to an organization with a role (and optional workspaces). */
export const invitations = pgTable(
    "invitations",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        /** Stored as typed; compared case-insensitively. */
        email: varchar("email", { length: 320 }).notNull(),
        role: organizationRole("role").notNull(),
        tokenHash: varchar("token_hash", { length: 64 }).notNull(),
        invitedBy: uuid("invited_by").references(() => accounts.id, { onDelete: "set null" }),
        expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
        acceptedAt: timestamp("accepted_at", { withTimezone: true }),
        acceptedBy: uuid("accepted_by").references(() => accounts.id, { onDelete: "set null" }),
        revokedAt: timestamp("revoked_at", { withTimezone: true }),
        revokedBy: uuid("revoked_by").references(() => accounts.id, { onDelete: "set null" }),
        /** Outcome of the last email sent for this invitation (null: never attempted). */
        lastDelivery: varchar("last_delivery", { length: 20 }),
        lastSentAt: timestamp("last_sent_at", { withTimezone: true }),
        sendCount: integer("send_count").notNull().default(0),
        createdAt: createdAt(),
    },
    (t) => [
        uniqueIndex("invitations_token_unique").on(t.tokenHash),
        // At most one open invitation per person and organization (a new one replaces the old one).
        uniqueIndex("invitations_org_email_open_unique")
            .on(t.organizationId, sql`lower(${t.email})`)
            .where(sql`${t.acceptedAt} is null and ${t.revokedAt} is null`),
        index("invitations_org_created_idx").on(t.organizationId, t.createdAt),
    ],
);

/** Workspaces an invitation grants on acceptance. */
export const invitationWorkspaces = pgTable(
    "invitation_workspaces",
    {
        invitationId: uuid("invitation_id")
            .notNull()
            .references(() => invitations.id, { onDelete: "cascade" }),
        organizationId: uuid("organization_id").notNull(),
        workspaceId: uuid("workspace_id").notNull(),
        role: workspaceRole("role").notNull(),
    },
    (t) => [
        primaryKey({ columns: [t.invitationId, t.workspaceId] }),
        foreignKey({
            name: "invitation_workspaces_workspace_fk",
            columns: [t.organizationId, t.workspaceId],
            foreignColumns: [workspaces.organizationId, workspaces.id],
        }).onDelete("cascade"),
    ],
);

/**
 * A self-service registration waiting for its email to be verified. Nothing else exists until the
 * link is used: the account, the organization, its owner membership and its first workspace are
 * then created in one transaction (no half-created organization, no squatted email address).
 */
export const signupRequests = pgTable(
    "signup_requests",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        email: varchar("email", { length: 320 }).notNull(),
        name: varchar("name", { length: 200 }).notNull(),
        passwordHash: text("password_hash").notNull(),
        organizationName: varchar("organization_name", { length: 200 }).notNull(),
        organizationSlug: varchar("organization_slug", { length: 64 }).notNull(),
        locale: varchar("locale", { length: 35 }),
        tokenHash: varchar("token_hash", { length: 64 }).notNull(),
        expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
        consumedAt: timestamp("consumed_at", { withTimezone: true }),
        ipAddress: inet("ip_address"),
        createdAt: createdAt(),
    },
    (t) => [
        uniqueIndex("signup_requests_token_unique").on(t.tokenHash),
        index("signup_requests_email_idx").on(sql`lower(${t.email})`),
        index("signup_requests_expires_idx").on(t.expiresAt),
    ],
);

export const passwordResets = pgTable(
    "password_resets",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        accountId: uuid("account_id")
            .notNull()
            .references(() => accounts.id, { onDelete: "cascade" }),
        tokenHash: varchar("token_hash", { length: 64 }).notNull(),
        expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
        usedAt: timestamp("used_at", { withTimezone: true }),
        ipAddress: inet("ip_address"),
        createdAt: createdAt(),
    },
    (t) => [
        uniqueIndex("password_resets_token_unique").on(t.tokenHash),
        index("password_resets_account_idx").on(t.accountId),
    ],
);

export const emailDeliveryStatus = pgEnum("email_delivery_status", ["sent", "failed", "not_configured"]);

/** Outcome of every email this server tried to send. Bodies are never stored (they carry secret links). */
export const emailDeliveries = pgTable(
    "email_deliveries",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        recipient: varchar("recipient", { length: 320 }).notNull(),
        /** e.g. "invitation", "signup_verification", "password_reset". */
        purpose: varchar("purpose", { length: 50 }).notNull(),
        status: emailDeliveryStatus("status").notNull(),
        /** Transport error code or class, never a message that could echo the content. */
        errorCode: varchar("error_code", { length: 200 }),
        organizationId: uuid("organization_id").references(() => organizations.id, { onDelete: "set null" }),
        createdAt: createdAt(),
    },
    (t) => [index("email_deliveries_created_idx").on(t.createdAt)],
);

/**
 * Time-limited, justified access of a platform administrator to one organization. Platform
 * administrators hold no right inside an organization they are not a member of without one.
 */
export const supportAccessGrants = pgTable(
    "support_access_grants",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        accountId: uuid("account_id")
            .notNull()
            .references(() => accounts.id, { onDelete: "cascade" }),
        reason: text("reason").notNull(),
        expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
        endedAt: timestamp("ended_at", { withTimezone: true }),
        createdAt: createdAt(),
    },
    (t) => [index("support_access_grants_account_org_idx").on(t.accountId, t.organizationId)],
);

// ---------------------------------------------------------------------------------------------
// Background jobs (durable, retried, idempotent)
//
// Work that changes another system (WorkAdventure's map-storage, pusher) is recorded here in the
// same transaction as the local change, then run by the worker (services/jobs.ts) with bounded
// retries and exponential backoff. `idempotencyKey` makes a second enqueue of the same work a no-op.
// ---------------------------------------------------------------------------------------------

export const jobStatus = pgEnum("job_status", ["pending", "running", "succeeded", "failed", "cancelled"]);

export const jobs = pgTable(
    "jobs",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        kind: varchar("kind", { length: 64 }).notNull(),
        /** Tenant of the job (null for platform jobs). Workers re-check it before acting. */
        organizationId: uuid("organization_id").references(() => organizations.id, { onDelete: "cascade" }),
        payload: jsonb("payload").$type<Record<string, unknown>>().notNull(),
        status: jobStatus("status").notNull().default("pending"),
        attempts: integer("attempts").notNull().default(0),
        maxAttempts: integer("max_attempts").notNull().default(6),
        runAfter: timestamp("run_after", { withTimezone: true }).notNull().defaultNow(),
        lockedAt: timestamp("locked_at", { withTimezone: true }),
        lockedBy: varchar("locked_by", { length: 100 }),
        /** Short, sanitized error of the last failed attempt (no secrets, no response bodies). */
        lastError: text("last_error"),
        result: jsonb("result").$type<Record<string, unknown>>(),
        idempotencyKey: varchar("idempotency_key", { length: 200 }),
        createdBy: uuid("created_by").references(() => accounts.id, { onDelete: "set null" }),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
        finishedAt: timestamp("finished_at", { withTimezone: true }),
    },
    (t) => [
        uniqueIndex("jobs_idempotency_unique")
            .on(t.idempotencyKey)
            .where(sql`${t.idempotencyKey} is not null`),
        index("jobs_status_run_after_idx").on(t.status, t.runAfter),
        index("jobs_org_created_idx").on(t.organizationId, t.createdAt),
    ],
);

// ---------------------------------------------------------------------------------------------
// Office components: catalog, versions, content-addressed assets, installations
//
// A component is furniture or decoration for WorkAdventure's inline map editor ("entity") or a
// complete room ("room_template"). Its versions are immutable once published and carry a validated
// manifest (src/lib/catalog/manifest.ts). Platform components (organization_id null) are visible to
// every organization; organization components only to their owner.
// ---------------------------------------------------------------------------------------------

/** Binary files (images, map files), stored once per content hash (SHA-256 of the bytes). */
export const assets = pgTable("assets", {
    sha256: varchar("sha256", { length: 64 }).primaryKey(),
    contentType: varchar("content_type", { length: 100 }).notNull(),
    byteSize: integer("byte_size").notNull(),
    width: integer("width"),
    height: integer("height"),
    data: bytea("data").notNull(),
    createdAt: createdAt(),
});

export const componentKind = pgEnum("component_kind", ["entity", "room_template"]);
export const componentStatus = pgEnum("component_status", ["draft", "published", "deprecated"]);

export const components = pgTable(
    "components",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        /** Stable identifier (lowercase slug), part of the prefab ids WorkAdventure stores in maps. */
        key: varchar("key", { length: 64 }).notNull(),
        /** Owner organization; null for the platform catalog shared by every organization. */
        organizationId: uuid("organization_id").references(() => organizations.id, { onDelete: "cascade" }),
        kind: componentKind("kind").notNull(),
        name: varchar("name", { length: 200 }).notNull(),
        description: text("description"),
        category: varchar("category", { length: 64 }).notNull(),
        tags: text("tags")
            .array()
            .notNull()
            .default(sql`'{}'::text[]`),
        status: componentStatus("status").notNull().default("draft"),
        /** SPDX license identifier of the assets, e.g. CC0-1.0. */
        license: varchar("license", { length: 100 }).notNull(),
        attribution: text("attribution"),
        /** Where the assets come from: "original" work, or a third-party source with its URL. */
        provenance: text("provenance").notNull(),
        publisher: varchar("publisher", { length: 200 }).notNull(),
        createdBy: uuid("created_by").references(() => accounts.id, { onDelete: "set null" }),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
    },
    (t) => [
        uniqueIndex("components_platform_key_unique")
            .on(t.key)
            .where(sql`${t.organizationId} is null`),
        uniqueIndex("components_org_key_unique")
            .on(t.organizationId, t.key)
            .where(sql`${t.organizationId} is not null`),
        index("components_category_idx").on(t.category),
        // Full-text search on name and description (to_tsvector with a constant configuration is immutable);
        // tags have their own index for the array overlap filter (tags && ...).
        index("components_search_idx").using(
            "gin",
            sql`to_tsvector('simple', ${t.name} || ' ' || coalesce(${t.description}, ''))`,
        ),
        index("components_tags_idx").using("gin", t.tags),
    ],
);

export const componentVersions = pgTable(
    "component_versions",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        componentId: uuid("component_id")
            .notNull()
            .references(() => components.id, { onDelete: "cascade" }),
        /** Semantic version (semver.org), e.g. 1.2.0. */
        version: varchar("version", { length: 32 }).notNull(),
        /** Validated manifest (ComponentManifest); never changed after publication. */
        manifest: jsonb("manifest").$type<Record<string, unknown>>().notNull(),
        manifestHash: varchar("manifest_hash", { length: 64 }).notNull(),
        /** Result of the last validation: { ok, issues: [{ code, path }] }. */
        validation: jsonb("validation").$type<{ ok: boolean; issues: { code: string; path: string }[] }>().notNull(),
        publishedAt: timestamp("published_at", { withTimezone: true }),
        createdBy: uuid("created_by").references(() => accounts.id, { onDelete: "set null" }),
        createdAt: createdAt(),
    },
    (t) => [uniqueIndex("component_versions_unique").on(t.componentId, t.version)],
);

/** Files of a version, by their path in the manifest. Assets are shared between versions (same hash). */
export const componentVersionAssets = pgTable(
    "component_version_assets",
    {
        versionId: uuid("version_id")
            .notNull()
            .references(() => componentVersions.id, { onDelete: "cascade" }),
        path: varchar("path", { length: 200 }).notNull(),
        sha256: varchar("sha256", { length: 64 })
            .notNull()
            .references(() => assets.sha256, { onDelete: "restrict" }),
    },
    (t) => [primaryKey({ columns: [t.versionId, t.path] }), index("component_version_assets_sha_idx").on(t.sha256)],
);

/** A component made available in a world (its entities appear in the world's map editor collection). */
export const componentInstallations = pgTable(
    "component_installations",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id").notNull(),
        worldId: uuid("world_id").notNull(),
        componentId: uuid("component_id")
            .notNull()
            .references(() => components.id, { onDelete: "cascade" }),
        versionId: uuid("version_id")
            .notNull()
            .references(() => componentVersions.id, { onDelete: "restrict" }),
        installedBy: uuid("installed_by").references(() => accounts.id, { onDelete: "set null" }),
        installedAt: createdAt(),
        updatedAt: updatedAt(),
    },
    (t) => [
        uniqueIndex("component_installations_world_component_unique").on(t.worldId, t.componentId),
        index("component_installations_org_idx").on(t.organizationId),
        foreignKey({
            name: "component_installations_world_fk",
            columns: [t.organizationId, t.worldId],
            foreignColumns: [worlds.organizationId, worlds.id],
        }).onDelete("cascade"),
    ],
);

export const componentFavorites = pgTable(
    "component_favorites",
    {
        accountId: uuid("account_id")
            .notNull()
            .references(() => accounts.id, { onDelete: "cascade" }),
        componentId: uuid("component_id")
            .notNull()
            .references(() => components.id, { onDelete: "cascade" }),
        createdAt: createdAt(),
    },
    (t) => [primaryKey({ columns: [t.accountId, t.componentId] })],
);

/** Named selections of components kept by an organization (e.g. "Paris office furniture"). */
export const componentCollections = pgTable(
    "component_collections",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        name: varchar("name", { length: 200 }).notNull(),
        description: text("description"),
        createdBy: uuid("created_by").references(() => accounts.id, { onDelete: "set null" }),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
    },
    (t) => [uniqueIndex("component_collections_org_name_unique").on(t.organizationId, t.name)],
);

export const componentCollectionItems = pgTable(
    "component_collection_items",
    {
        collectionId: uuid("collection_id")
            .notNull()
            .references(() => componentCollections.id, { onDelete: "cascade" }),
        componentId: uuid("component_id")
            .notNull()
            .references(() => components.id, { onDelete: "cascade" }),
        position: integer("position").notNull().default(0),
    },
    (t) => [primaryKey({ columns: [t.collectionId, t.componentId] })],
);

// ---------------------------------------------------------------------------------------------
// Integration Center (src/lib/server/integrations, docs/INTEGRATIONS.md)
//
// Connections to third-party services (organization-wide, or personal to one account), outgoing notifications
// (endpoints, events, deliveries) and the automation API. Credentials are sealed at rest with the application key
// (services/secrets.ts): OAuth tokens, webhook URLs and signing secrets; automation tokens are stored as SHA-256
// like Room API keys. None of them is ever sent to a browser.
// ---------------------------------------------------------------------------------------------

/**
 * `pending`: configured but not proven yet (an inbound webhook receiver before its first verified call). A connection
 * is `connected` only after a real successful call to the provider.
 */
export const integrationStatus = pgEnum("integration_status", [
    "not_configured",
    "pending",
    "connected",
    "error",
    "revoked",
    "expired",
]);

export const integrationConnections = pgTable(
    "integration_connections",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        /** The person a personal connection belongs to; null for an organization-wide connection. */
        accountId: uuid("account_id").references(() => accounts.id, { onDelete: "cascade" }),
        /** Provider id of the registry (src/lib/server/integrations/registry.ts), e.g. "google". */
        provider: varchar("provider", { length: 32 }).notNull(),
        status: integrationStatus("status").notNull().default("not_configured"),
        /** Scopes the provider actually granted (not the ones asked for). */
        scopes: text("scopes")
            .array()
            .notNull()
            .default(sql`'{}'::text[]`),
        externalAccountId: varchar("external_account_id", { length: 200 }),
        externalAccountName: varchar("external_account_name", { length: 200 }),
        /** Sealed. */
        accessToken: text("access_token"),
        /** Sealed. Providers that rotate refresh tokens get the new one stored at every refresh. */
        refreshToken: text("refresh_token"),
        /** Sealed secret of an inbound webhook receiver (GitHub, GitLab) or of a Slack incoming-webhook URL. */
        secret: text("secret"),
        /** When the access token expires (null: it does not, or the provider does not say). */
        expiresAt: timestamp("expires_at", { withTimezone: true }),
        lastTestedAt: timestamp("last_tested_at", { withTimezone: true }),
        lastSyncAt: timestamp("last_sync_at", { withTimezone: true }),
        /** Last time WorkAdventure asked for this person's data: background sync runs only while it is useful. */
        lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
        /** Short error code of the last failure (never a provider's message, which could echo a token). */
        lastError: varchar("last_error", { length: 300 }),
        /** Typed and validated by IntegrationSettings (src/lib/settings/integrationSettings.ts). */
        settings: jsonb("settings").$type<IntegrationSettings>().notNull().default({}),
        /** Latest shared coding activity of a personal GitHub/GitLab connection. */
        activity: jsonb("activity").$type<IntegrationActivity>(),
        /**
         * Lease of the token refresh in progress: refresh tokens rotate at some providers, so two concurrent refreshes
         * would invalidate each other. Claimed with a conditional UPDATE, never held during a database transaction.
         */
        refreshLockedUntil: timestamp("refresh_locked_until", { withTimezone: true }),
        createdBy: uuid("created_by").references(() => accounts.id, { onDelete: "set null" }),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
    },
    (t) => [
        // One organization-wide connection per provider, and one personal connection per person and provider.
        uniqueIndex("integration_connections_org_provider_unique")
            .on(t.organizationId, t.provider)
            .where(sql`${t.accountId} is null`),
        uniqueIndex("integration_connections_personal_unique")
            .on(t.organizationId, t.provider, t.accountId)
            .where(sql`${t.accountId} is not null`),
        index("integration_connections_account_idx").on(t.accountId),
        index("integration_connections_external_idx").on(t.provider, t.externalAccountId),
        check("integration_connections_provider_check", sql`${t.provider} ~ '^[a-z0-9-]{2,32}$'`),
    ],
);

/**
 * OAuth authorization requests in flight: the `state` parameter (only its SHA-256 here) and the PKCE verifier
 * (sealed). Single use, valid 10 minutes, bound to the account that started the flow.
 */
export const integrationOauthStates = pgTable(
    "integration_oauth_states",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        stateHash: varchar("state_hash", { length: 64 }).notNull(),
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        accountId: uuid("account_id")
            .notNull()
            .references(() => accounts.id, { onDelete: "cascade" }),
        provider: varchar("provider", { length: 32 }).notNull(),
        /** A personal connection (true) or the organization's (false). */
        personal: boolean("personal").notNull(),
        /** Sealed PKCE code verifier (RFC 7636); null for flows without PKCE (Trello's token flow). */
        codeVerifier: text("code_verifier"),
        /** The exact redirect URI sent with the authorization request (the token request must repeat it). */
        redirectUri: text("redirect_uri").notNull(),
        /** Back-office path to return to (checked with safeRedirectPath). */
        returnTo: varchar("return_to", { length: 300 }).notNull(),
        expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
        consumedAt: timestamp("consumed_at", { withTimezone: true }),
        createdAt: createdAt(),
    },
    (t) => [
        uniqueIndex("integration_oauth_states_hash_unique").on(t.stateHash),
        index("integration_oauth_states_expires_idx").on(t.expiresAt),
    ],
);

export const integrationEndpointKind = pgEnum("integration_endpoint_kind", [
    "slack",
    "discord",
    "teams",
    "webhook",
    "zapier",
    "n8n",
]);

/** Where an organization's events are sent: a chat channel or a webhook URL, and which events it receives. */
export const integrationEndpoints = pgTable(
    "integration_endpoints",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        kind: integrationEndpointKind("kind").notNull(),
        name: varchar("name", { length: 200 }).notNull(),
        /** Sealed: for Discord, Teams, Zapier and Slack incoming webhooks the URL itself is the credential. */
        url: text("url"),
        /** What may be shown of the URL (scheme, host and the start of the path). */
        urlHint: varchar("url_hint", { length: 200 }),
        /** Slack channel posted to with the organization's Slack connection (chat.postMessage), when no URL. */
        channel: varchar("channel", { length: 100 }),
        /** Sealed "whsec_" secret signing the Standard Webhooks requests of webhook, Zapier and n8n endpoints. */
        signingSecret: text("signing_secret"),
        /** Event types (src/lib/server/integrations/events.ts) the endpoint receives. */
        eventTypes: text("event_types")
            .array()
            .notNull()
            .default(sql`'{}'::text[]`),
        enabled: boolean("enabled").notNull().default(true),
        /** Failed deliveries in a row; an endpoint that keeps failing is disabled (Discord bans abusive IPs). */
        consecutiveFailures: integer("consecutive_failures").notNull().default(0),
        /** Why the endpoint was disabled automatically: "gone" (410), "unauthorized", "failing". */
        disabledReason: varchar("disabled_reason", { length: 50 }),
        lastSuccessAt: timestamp("last_success_at", { withTimezone: true }),
        lastFailureAt: timestamp("last_failure_at", { withTimezone: true }),
        lastError: varchar("last_error", { length: 300 }),
        createdBy: uuid("created_by").references(() => accounts.id, { onDelete: "set null" }),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
    },
    (t) => [
        // Target of the composite foreign key of deliveries: a delivery names an endpoint of its own organization.
        unique("integration_endpoints_org_id_unique").on(t.organizationId, t.id),
        index("integration_endpoints_org_idx").on(t.organizationId),
    ],
);

/** Events of an organization sent to its endpoints (member.invited, desk.assigned, ...), stored once. */
export const integrationEvents = pgTable(
    "integration_events",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        type: varchar("type", { length: 64 }).notNull(),
        data: jsonb("data").$type<Record<string, unknown>>().notNull(),
        occurredAt: timestamp("occurred_at", { withTimezone: true }).notNull().defaultNow(),
    },
    (t) => [
        unique("integration_events_org_id_unique").on(t.organizationId, t.id),
        index("integration_events_org_time_idx").on(t.organizationId, t.occurredAt),
    ],
);

export const integrationDeliveryStatus = pgEnum("integration_delivery_status", ["pending", "succeeded", "failed"]);

/** One event sent to one endpoint: the delivery log. Unique per endpoint and event (idempotent). */
export const integrationDeliveries = pgTable(
    "integration_deliveries",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id").notNull(),
        eventId: uuid("event_id").notNull(),
        endpointId: uuid("endpoint_id").notNull(),
        status: integrationDeliveryStatus("status").notNull().default("pending"),
        attempts: integer("attempts").notNull().default(0),
        /** HTTP status of the last answer (null: no answer, e.g. a timeout). */
        responseStatus: integer("response_status"),
        /** Short error code of the last failed attempt. */
        lastError: varchar("last_error", { length: 300 }),
        createdAt: createdAt(),
        updatedAt: updatedAt(),
        /** When it succeeded or finally failed. */
        finishedAt: timestamp("finished_at", { withTimezone: true }),
    },
    (t) => [
        uniqueIndex("integration_deliveries_endpoint_event_unique").on(t.endpointId, t.eventId),
        index("integration_deliveries_org_created_idx").on(t.organizationId, t.createdAt),
        index("integration_deliveries_org_status_idx").on(t.organizationId, t.status),
        foreignKey({
            name: "integration_deliveries_endpoint_fk",
            columns: [t.organizationId, t.endpointId],
            foreignColumns: [integrationEndpoints.organizationId, integrationEndpoints.id],
        }).onDelete("cascade"),
        foreignKey({
            name: "integration_deliveries_event_fk",
            columns: [t.organizationId, t.eventId],
            foreignColumns: [integrationEvents.organizationId, integrationEvents.id],
        }).onDelete("cascade"),
    ],
);

/**
 * Bearer tokens of the automation API (/automation/v1: Zapier, n8n, scripts). Only a SHA-256 is stored; the clear
 * token is shown once. A token acts with the current rights of the person who created it, within its scopes.
 */
export const automationTokens = pgTable(
    "automation_tokens",
    {
        id: uuid("id").primaryKey().defaultRandom(),
        organizationId: uuid("organization_id")
            .notNull()
            .references(() => organizations.id, { onDelete: "cascade" }),
        name: varchar("name", { length: 200 }).notNull(),
        tokenHash: varchar("token_hash", { length: 64 }).notNull(),
        tokenPrefix: varchar("token_prefix", { length: 16 }).notNull(),
        /** e.g. "invitations:write", "announcements:write" (src/lib/server/integrations/automation.ts). */
        scopes: text("scopes")
            .array()
            .notNull()
            .default(sql`'{}'::text[]`),
        createdBy: uuid("created_by").references(() => accounts.id, { onDelete: "set null" }),
        lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
        expiresAt: timestamp("expires_at", { withTimezone: true }),
        revokedAt: timestamp("revoked_at", { withTimezone: true }),
        createdAt: createdAt(),
    },
    (t) => [
        uniqueIndex("automation_tokens_hash_unique").on(t.tokenHash),
        index("automation_tokens_org_idx").on(t.organizationId),
    ],
);

/** Inbound webhook deliveries already processed (GitHub X-GitHub-Delivery, GitLab, Slack event ids): no replay. */
export const integrationInboundEvents = pgTable(
    "integration_inbound_events",
    {
        provider: varchar("provider", { length: 32 }).notNull(),
        externalId: varchar("external_id", { length: 200 }).notNull(),
        organizationId: uuid("organization_id").references(() => organizations.id, { onDelete: "cascade" }),
        receivedAt: timestamp("received_at", { withTimezone: true }).notNull().defaultNow(),
    },
    (t) => [
        primaryKey({ columns: [t.provider, t.externalId] }),
        index("integration_inbound_events_received_idx").on(t.receivedAt),
    ],
);

// ---------------------------------------------------------------------------------------------
// Who's in: live presence reported by WorkAdventure (docs/PRESENCE.md)
// ---------------------------------------------------------------------------------------------

/**
 * The latest report of each pusher (POST /api/presence/report): who is connected to it right now, already resolved to
 * AdminSpace organizations, worlds and rooms. A report replaces the previous one of the same pusher in a single upsert;
 * a row past `expires_at` is stale, never read, and deleted opportunistically. Nothing historical is kept: there is no
 * log of who was connected when. One row per pusher (a handful) holding a JSON list, rather than one row per person:
 * a report is a whole-list replacement every few seconds, read only by the "Who's in" page.
 */
export const presenceReports = pgTable(
    "presence_reports",
    {
        instanceId: varchar("instance_id", { length: 200 }).primaryKey(),
        /** As claimed by the pusher: only orders the reports of one pusher. */
        reportedAt: timestamp("reported_at", { withTimezone: true }).notNull(),
        receivedAt: timestamp("received_at", { withTimezone: true }).notNull().defaultNow(),
        /** receivedAt + ttlSeconds (clamped): the report holds until then. */
        expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
        /** People in rooms this AdminSpace manages (src/lib/presence/model.ts PresenceEntry). */
        users: jsonb("users").$type<PresenceEntry[]>().notNull().default([]),
    },
    (t) => [index("presence_reports_expires_idx").on(t.expiresAt)],
);
